import {run} from './packages/safe-js/src/run.ts';
import {dump} from './packages/safe-js/src/dump.ts';
const results=[];
for(const kind of ['sync','async']) {
 const trace=[];
 const reason=new Proxy(new Error('private-host-diagnostic'),{getPrototypeOf(t){trace.push('getPrototypeOf');return Reflect.getPrototypeOf(t)},get(t,k,r){trace.push('get:'+String(k));return Reflect.get(t,k,r)},getOwnPropertyDescriptor(t,k){trace.push('descriptor:'+String(k));return Reflect.getOwnPropertyDescriptor(t,k)}});
 let calls=0;
 const fail=kind==='sync'?()=>{calls++;throw reason}:async()=>{calls++;throw reason};
 const source="try{await fail()}catch(e){return [e.name,e.message,e.stack]}";
 try {
  const original=await run(source,{bindings:{fail}});
  const originalTrace=[...trace];
  const replay=await run(source,{bindings:{fail},snapshot:JSON.parse(await dump(original))});
  results.push({kind,original:original.returnValue,replay:replay.returnValue,calls,originalTrace,trace});
 }catch(e){results.push({kind,failed:String(e),calls,trace})}
}
const owner=await run("return [(function(){'use strict';return arguments})(), Object.getOwnPropertyDescriptor(Function.prototype,'caller').get,TypeError.prototype]");
const caller=await run("return (args,restricted,prototype)=>{const t=[];const getter=Object.getOwnPropertyDescriptor(args,'callee').get;t.push(getter===restricted);try{getter()}catch(e){t.push(Object.getPrototypeOf(e)===prototype,e instanceof TypeError)}finally{t.push('finally')}return t}");
try{results.push({kind:'foreign-arguments',expected:[true,true,false,'finally'],actual:await caller.returnValue.call(owner.returnValue)})}catch(e){results.push({kind:'foreign-arguments',expected:[true,true,false,'finally'],failed:{name:Object.getOwnPropertyDescriptor(e,'name')?.value,message:Object.getOwnPropertyDescriptor(e,'message')?.value,kind:Object.getOwnPropertyDescriptor(e,'kind')?.value}})}
console.log(JSON.stringify(results,null,2));
